using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Sphere of Annihilation (2014 ruleset). SRD 5.1 text (CC BY 4.0) in English and in the official Italian SRD 5.1 (CC BY 4.0).
///	</summary>
public static class SphereOfAnnihilation2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("sphere-of-annihilation", null, 0, MagicItemType.WondrousItem, ItemRarity.Legendary, false, ContentSource.Srd51,
			null,
			("Sfera annientatrice", "Oggetto meraviglioso, leggendario",
			"Questa sfera nera del diametro di 60 cm è un buco nel multiverso che fluttua a mezz'aria e che è stabilizzato da un campo magico che la circonda.\n\nLa sfera annienta tutta la materia che attraversa e che passa attraverso di essa, a eccezione dei manufatti. A meno che un manufatto non sia suscettibile ai danni di una *sfera annientatrice,* esso vi passa attraverso e ne esce illeso. Ogni altra cosa che tocca la sfera, ma che non ne viene interamente inghiottita e annientata, subisce 4d10 danni da forza.\n\nLa sfera rimane stazionaria finché qualcuno non ne prende il controllo. Se il personaggio si trova entro 18 metri da una sfera non controllata, può usare un'azione per effettuare una prova di Intelligenza (Arcano) con CD 25. In caso di successo, la sfera levita in una direzione scelta dal personaggio, fino a un numero di metri pari a 1,5 × il suo modificatore di Intelligenza (per un minimo di 1,5 metri). In caso di fallimento, la sfera si muove di 3 metri verso il personaggio. Se la sfera entra nello spazio occupato da una creatura, quest'ultima deve superare un tiro salvezza su Destrezza con CD 13 per non farsi toccare, altrimenti subisce 4d10 danni da forza.\n\nSe il personaggio tenta di controllare una sfera che si trova sotto il controllo di un'altra creatura, deve effettuare una prova di Intelligenza (Arcano) contrapposta a quella dell'altra creatura. Chi vince ottiene il controllo della sfera e può farla levitare normalmente.\n\nSe la sfera entra in contatto con un portale planare, come quello creato dall'incantesimo *portale,* o con uno spazio extradimensionale, come quello di un *buco portatile,* il GM determina casualmente ciò che succede, usando la tabella seguente.\n\n| d100 | Risultato |\n|---|---|\n| 01–50 | La sfera è distrutta. |\n| 51–85 | La sfera si muove attraverso il portale o nello spazio extradimensionale. |\n| 86–00 | Uno squarcio nello spazio trascina ogni creatura e oggetto entro 54 metri dalla sfera (inclusa la sfera stessa) su un piano di esistenza casuale. |"),
			("Sphere of Annihilation", "Wondrous item, legendary",
			"This 2-foot-diameter black sphere is a hole in the multiverse, hovering in space and stabilized by a magical field surrounding it.\n\nThe sphere obliterates all matter it passes through and all matter that passes through it. Artifacts are the exception. Unless an artifact is susceptible to damage from a sphere of annihilation, it passes through the sphere unscathed. Anything else that touches the sphere but isn't wholly engulfed and obliterated by it takes 4d10 force damage.\n\nThe sphere is stationary until someone controls it. If you are within 60 feet of an uncontrolled sphere, you can use an action to make a DC 25 Intelligence (Arcana) check. On a success, the sphere levitates in one direction of your choice, up to a number of feet equal to 5 × your Intelligence modifier (minimum 5 feet). On a failure, the sphere moves 10 feet toward you. A creature whose space the sphere enters must succeed on a DC 13 Dexterity saving throw or be touched by it, taking 4d10 force damage.\n\nIf you attempt to control a sphere that is under another creature's control, you make an Intelligence (Arcana) check contested by the other creature's Intelligence (Arcana) check. The winner of the contest gains control of the sphere and can levitate it as normal.\n\nIf the sphere comes into contact with a planar portal, such as that created by the gate spell, or an extradimensional space, such as that within a portable hole, the GM determines randomly what happens, using the following table.\n\n| d100 | Result |\n|---|---|\n| 01-50 | The sphere is destroyed. |\n| 51-85 | The sphere moves through the portal or into the extradimensional space. |\n| 86-00 | A spatial rift sends each creature and object within 180 feet of the sphere, including the sphere, to a random plane of existence. |", null));
	}
}
